<!DOCTYPE html><html lang="en"><?= view('components/head',['pageTitle'=>$pageTitle]) ?><body><?= view('components/header') ?><main class="container-fluid"><div class="row admin-layout"><?= view('components/admin_sidebar') ?><section class="col admin-content"><p class="eyebrow">Fulfillment</p><h1 class="section-title mb-4">Order #<?= esc($orderId) ?></h1><div id="sync-message"></div><div class="row g-4"><div class="col-xl-8"><div class="surface-card p-4 mb-4"><h2 class="h4">Customer & delivery</h2><dl class="row mb-0"><dt class="col-sm-4">Customer</dt><dd class="col-sm-8"><?= esc($user->display_name ?? $user->username ?? '') ?> · <?= esc($user->email ?? '') ?></dd><dt class="col-sm-4">Phone</dt><dd class="col-sm-8"><?= esc($order['phone']) ?></dd><dt class="col-sm-4">Address</dt><dd class="col-sm-8"><?= esc(implode(', ', [$order['address'], $order['city'], $order['region'], $order['postal_code']])) ?></dd><dt class="col-sm-4">Delivery method</dt><dd class="col-sm-8"><?= esc($order['delivery_method']) ?></dd><dt class="col-sm-4">Payment reference</dt><dd class="col-sm-8"><?= esc($order['payment_reference']) ?></dd><dt class="col-sm-4">Proof of payment</dt><dd class="col-sm-8"><a href="/admin/orders/<?= esc($orderId) ?>/proof">Download protected file</a></dd><?php if (!empty($order['comments'])): ?><dt class="col-sm-4">Comments</dt><dd class="col-sm-8"><?= nl2br(esc($order['comments'])) ?></dd><?php endif; ?></dl></div><div class="surface-card p-4"><h2 class="h4">Order items</h2><?php foreach ($items as $item): ?><div class="d-flex align-items-center gap-3 py-3 border-bottom"><div class="cart-thumb"><i class="fa-solid fa-gift"></i></div><div class="flex-grow-1"><strong><?= esc($item['product_name']) ?></strong><small class="d-block text-muted-brand"><?= $item['variant'] ? esc($item['variant']) . ' · ' : '' ?>Qty <?= esc($item['quantity']) ?></small></div><strong>₱<?= number_format($item['line_total'], 2) ?></strong></div><?php endforeach; ?><div class="d-flex justify-content-end gap-4 pt-4"><strong>Total</strong><strong>₱<?= number_format($order['total'], 2) ?></strong></div></div></div><div class="col-xl-4"><form method="post" action="/admin/orders/<?= esc($orderId) ?>/status" class="surface-card p-4 mb-4"><h2 class="h4">Update status</h2><select class="form-select my-3" name="status"><?php foreach (['received','approved','shipped','delivered','cancelled'] as $status): ?><option value="<?= $status ?>" <?= $order['status'] === $status ? 'selected' : '' ?>><?= ucfirst($status) ?></option><?php endforeach; ?></select><button class="btn btn-brand w-100">Save status</button></form><div class="surface-card p-4"><h2 class="h4">Jotform sync</h2><p><span class="badge <?= $order['jotform_status'] === 'synced' ? 'text-bg-success' : ($order['jotform_status'] === 'failed' ? 'text-bg-danger' : 'text-bg-secondary') ?>"><?= esc(str_replace('_', ' ', ucfirst($order['jotform_status']))) ?></span></p><?php if ($order['jotform_submission_id']): ?><p class="small text-muted-brand">Submission: <?= esc($order['jotform_submission_id']) ?></p><?php endif; ?><?php if ($order['jotform_error']): ?><p class="small text-danger"><?= esc($order['jotform_error']) ?></p><?php endif; ?><?php if ($order['jotform_status'] !== 'synced'): ?><button class="btn btn-outline-brand w-100" type="button" id="retry-sync">Retry sync</button><?php endif; ?></div></div></div></section></div></main><script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.8/dist/js/bootstrap.bundle.min.js"></script><script>document.getElementById('retry-sync')?.addEventListener('click',async function(){this.disabled=true;this.textContent='Syncing…';const box=document.getElementById('sync-message');try{const response=await fetch('/api/jotform/orders/<?= esc($orderId) ?>',{method:'POST',headers:{'Accept':'application/json'}});const result=await response.json();if(!response.ok)throw new Error(result.message||'Sync failed');box.innerHTML='<div class="alert alert-success">Order synchronized with Jotform.</div>';location.reload();}catch(error){box.innerHTML='<div class="alert alert-danger"></div>';box.firstElementChild.textContent=error.message;this.disabled=false;this.textContent='Retry sync';}});</script></body></html>
